-- ETL batch loads, data cleanup and DBA administration queries
INSERT INTO dim_customer (customer_id, email, segment) SELECT u.id, LOWER(TRIM(u.email)), CASE WHEN s.total > 1000 THEN 'gold' ELSE 'std' END FROM users u LEFT JOIN (SELECT user_id, SUM(total) AS total FROM orders GROUP BY user_id) s ON s.user_id = u.id ON DUPLICATE KEY UPDATE email = VALUES(email), segment = VALUES(segment);
INSERT INTO daily_sales (day, revenue, orders) SELECT DATE(created_at), SUM(total), COUNT(*) FROM orders WHERE created_at >= CURDATE() - INTERVAL 1 DAY AND created_at < CURDATE() GROUP BY DATE(created_at);
UPDATE dim_customer c JOIN (SELECT user_id, MAX(created_at) AS last_order FROM orders GROUP BY user_id) o ON o.user_id = c.customer_id SET c.last_order = o.last_order;
UPDATE orders SET status = CASE id WHEN 1 THEN 'paid' WHEN 2 THEN 'shipped' ELSE status END WHERE id IN (1, 2, 3);
UPDATE users SET email = LOWER(email), name = TRIM(name) WHERE email <> LOWER(email);
UPDATE t1, t2 SET t1.a = t2.b WHERE t1.id = t2.id;
UPDATE IGNORE products SET sku = UPPER(sku);
DELETE FROM audit_log WHERE at < NOW() - INTERVAL 90 DAY LIMIT 10000;
DELETE t1 FROM t1 INNER JOIN t2 ON t1.id = t2.id WHERE t2.flag = 1;
DELETE FROM t1 USING t1 INNER JOIN t2 ON t1.id = t2.id;
INSERT INTO archive.orders SELECT * FROM orders WHERE created_at < '2023-01-01';
INSERT INTO ledger (account, amount) VALUES (1, -5.00), (2, 5.00);
INSERT INTO t (a, b) VALUES (1, DEFAULT), (DEFAULT, 2);
INSERT INTO t () VALUES ();
INSERT INTO t1 (a) VALUES (1) ON DUPLICATE KEY UPDATE a = a + VALUES(a), b = IF(b IS NULL, 1, b);
LOAD DATA INFILE '/tmp/users.csv' INTO TABLE users FIELDS TERMINATED BY ',' OPTIONALLY ENCLOSED BY '"' LINES TERMINATED BY '\n' IGNORE 1 LINES (email, name);
SELECT * FROM orders INTO OUTFILE '/tmp/orders.csv' FIELDS TERMINATED BY ',' LINES TERMINATED BY '\n';
SELECT table_schema, SUM(data_length + index_length) / 1024 / 1024 AS size_mb FROM information_schema.tables GROUP BY table_schema ORDER BY size_mb DESC;
SELECT table_name, engine, table_rows FROM information_schema.tables WHERE table_schema = 'shop' AND table_type = 'BASE TABLE';
SELECT column_name, data_type, is_nullable FROM information_schema.columns WHERE table_schema = 'shop' AND table_name = 'users' ORDER BY ordinal_position;
SELECT constraint_name, referenced_table_name FROM information_schema.key_column_usage WHERE table_schema = DATABASE() AND referenced_table_name IS NOT NULL;
SELECT id, user, host, db, command, time, state, info FROM information_schema.processlist WHERE command <> 'Sleep' AND time > 10 ORDER BY time DESC;
SELECT @@global.max_connections, @@session.sql_mode, @@version, @@innodb_buffer_pool_size;
SELECT * FROM mysql.slow_log ORDER BY start_time DESC LIMIT 50;
KILL 1234;
KILL QUERY 1234;
SELECT t.table_name FROM information_schema.tables t LEFT JOIN information_schema.statistics s ON s.table_schema = t.table_schema AND s.table_name = t.table_name WHERE s.index_name IS NULL AND t.table_schema = 'shop';
SELECT COUNT(*) AS dupes, email FROM users GROUP BY email HAVING COUNT(*) > 1;
SELECT u1.id, u2.id FROM users u1 JOIN users u2 ON u1.email = u2.email AND u1.id < u2.id;
SELECT * FROM orders o WHERE o.total > (SELECT AVG(total) FROM orders WHERE user_id = o.user_id);
SELECT * FROM orders WHERE (user_id, created_at) IN (SELECT user_id, MAX(created_at) FROM orders GROUP BY user_id);
SELECT * FROM products WHERE price > ALL (SELECT price FROM products WHERE category_id = 2);
SELECT * FROM products WHERE price > ANY (SELECT price FROM products WHERE category_id = 2);
SELECT * FROM users WHERE id = (SELECT MAX(id) FROM users);
SELECT 1 FROM DUAL;
SELECT NULL, TRUE, FALSE, 0x1F, X'1F', b'101', 1.5e3, .5, 'it''s', "dq";
SELECT _utf8mb4'abc' COLLATE utf8mb4_bin, BINARY name, name COLLATE utf8mb4_general_ci FROM users;
SELECT @rownum := @rownum + 1 AS rn, t.* FROM t, (SELECT @rownum := 0) r;
PREPARE stmt FROM 'SELECT * FROM users WHERE id = ?';
EXECUTE stmt USING @id;
DEALLOCATE PREPARE stmt;
